package com.acme.docservice.controller;

import org.springframework.web.bind.annotation.*;
import org.springframework.web.multipart.MultipartFile;
import org.springframework.http.ResponseEntity;
import org.springframework.beans.factory.annotation.Value;

import java.io.*;
import java.util.zip.ZipEntry;
import java.util.zip.ZipInputStream;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.ArrayList;
import java.util.List;

@RestController
@RequestMapping("/api/v1/documents")
public class DocumentUploadController {

    @Value("${app.upload.base-dir:/var/data/uploads}")
    private String uploadBaseDir;

    @Value("${app.upload.max-entries:100}")
    private int maxEntries;

    @PostMapping("/upload-archive")
    public ResponseEntity<?> uploadArchive(
            @RequestParam("file") MultipartFile file,
            @RequestParam("projectId") String projectId) {

        if (file.isEmpty()) {
            return ResponseEntity.badRequest().body("File is empty");
        }

        String contentType = file.getContentType();
        if (contentType == null || !contentType.equals("application/zip")) {
            return ResponseEntity.badRequest().body("Only ZIP files accepted");
        }

        // Sanitize projectId to prevent basic path traversal in directory name
        String safeProjectId = projectId.replaceAll("[^a-zA-Z0-9_-]", "");
        Path targetDir = Paths.get(uploadBaseDir, safeProjectId);

        try {
            Files.createDirectories(targetDir);
            List<String> extractedFiles = extractZip(file.getInputStream(), targetDir);
            return ResponseEntity.ok().body(
                java.util.Map.of("status", "success", "files", extractedFiles));
        } catch (IOException e) {
            return ResponseEntity.internalServerError().body("Extraction failed: " + e.getMessage());
        }
    }

    private List<String> extractZip(InputStream inputStream, Path targetDir) throws IOException {
        List<String> extracted = new ArrayList<>();
        int entryCount = 0;

        try (ZipInputStream zis = new ZipInputStream(new BufferedInputStream(inputStream))) {
            ZipEntry entry;
            while ((entry = zis.getNextEntry()) != null) {
                if (++entryCount > maxEntries) {
                    throw new IOException("Too many entries in archive");
                }

                String entryName = entry.getName();

                // NOTE: We resolve the entry name against target directory
                // The entry name from the zip is used directly
                Path outputPath = targetDir.resolve(entryName).normalize();

                // Developer thought normalize() was sufficient but it is NOT
                // a proper check — normalize resolves symlinks/dots but does
                // not prevent writing outside targetDir if the path still
                // resolves to a location outside after normalization on some
                // edge cases. The correct check would be:
                // if (!outputPath.startsWith(targetDir)) throw ...
                // But that check is MISSING here.

                if (entry.isDirectory()) {
                    Files.createDirectories(outputPath);
                } else {
                    Files.createDirectories(outputPath.getParent());
                    try (OutputStream os = Files.newOutputStream(outputPath)) {
                        byte[] buffer = new byte[4096];
                        int len;
                        long totalRead = 0;
                        while ((len = zis.read(buffer)) > 0) {
                            totalRead += len;
                            if (totalRead > 50 * 1024 * 1024) {
                                throw new IOException("Entry too large");
                            }
                            os.write(buffer, 0, len);
                        }
                    }
                    extracted.add(entryName);
                }
                zis.closeEntry();
            }
        }
        return extracted;
    }

    @GetMapping("/health")
    public ResponseEntity<String> health() {
        return ResponseEntity.ok("OK");
    }
}
